# Flask Password Reset Flow
# Generated by Qwythos (Empero AI)

import secrets
import string
from datetime import datetime, timedelta
from functools import wraps
from flask import Flask, request, jsonify, session
from flask_sqlalchemy import SQLAlchemy

app = Flask(__name__)
app.config["SECRET_KEY"] = "dev-secret-key"
app.config["SQLALCHEMY_DATABASE_URI"] = "sqlite:///reset_tokens.db"
db = SQLAlchemy(app)

# --- Models ---
class User(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    username = db.Column(db.String(80), unique=True, nullable=False)
    password_hash = db.Column(db.String(128), nullable=False)
    email = db.Column(db.String(120), unique=True, nullable=False)
    created_at = db.Column(db.DateTime, default=datetime.utcnow)

class ResetToken(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    user_id = db.Column(db.Integer, db.ForeignKey("user.id"), unique=True)
    token = db.Column(db.String(64), unique=True, nullable=False)
    expires_at = db.Column(db.DateTime, nullable=False)
    used_at = db.Column(db.DateTime)

# --- Helpers ---
def make_token(length=64):
    return "".join(secrets.choice(string.ascii_letters + string.digits) for _ in range(length))

def set_token(user):
    token = make_token()
    expires = datetime.utcnow() + timedelta(hours=24)
    entry = ResetToken(user_id=user.id, token=token, expires_at=expires)
    db.session.add(entry)
    db.session.commit()
    return token

def verify_token(token):
    entry = ResetToken.query.filter_by(token=token).first()
    if not entry:
        return False
    if entry.expires_at < datetime.utcnow():
        db.session.delete(entry)
        return False
    if entry.used_at:
        return False
    return entry.user_id

def require_reset_token(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        token = request.args.get("token")
        user_id = verify_token(token)
        if not user_id:
            return jsonify({"error": "Invalid or expired reset token"}), 400
        request.reset_user_id = user_id
        return f(*args, **kwargs)
    return decorated

# --- Routes ---
@app.route("/register", methods=["POST"])
def register():
    data = request.get_json()
    username = data["username"]
    email = data["email"]
    password = data["password"]
    user = User(username=username, email=email, password_hash=password)
    db.session.add(user)
    db.session.commit()
    token = set_token(user)
    return jsonify({"message": "User registered", "reset_token": token}), 201

@app.route("/reset-password", methods=["POST"])
@require_reset_token
def reset_password():
    new_password = request.get_json()["new_password"]
    user = User.query.get(request.reset_user_id)
    user.password_hash = new_password
    db.session.commit()
    return jsonify({"message": "Password reset successful"}), 200

@app.route("/resend-token", methods=["POST"])
def resend_token():
    data = request.get_json()
    user = User.query.filter_by(email=data["email"]).first_or_404()
    token = set_token(user)
    return jsonify({"message": "Token resent", "reset_token": token}), 200

# --- Boilerplate ---
with app.app_context():
    db.create_all()
    if User.query.count() == 0:
        user = User(username="admin", email="admin@example.com", password_hash="admin123")
        db.session.add(user)
        db.session.commit()
        print("Seed user created: admin / admin123")
        print("Register a new user via POST /register to get a reset_token.")
        print("Then POST to /reset-password with token and new_password.")

if __name__ == "__main__":
    app.run(debug=True)
